INSERT INTO `cursos` VALUES (1,'ingles-dia-a-dia','Inglés para el día a día','Inglés','Saludos, presentaciones y el inglés del salón de clase. Nivel A1.',NULL,NULL,NULL,NULL,'publicado',1,'2026-10-26 19:01:01'),(2,'agua-en-la-tierra','El agua en la Tierra','Ciencias naturales','Estados y ciclo del agua, ríos de Colombia y cómo cuidarlos.',NULL,NULL,NULL,NULL,'publicado',1,'2026-10-26 19:01:01'),(3,'independencia-colombia','Independencia de Colombia','Ciencias sociales','Del 20 de julio de 1810 a la Batalla de Boyacá y la Gran Colombia.',NULL,NULL,NULL,NULL,'publicado',1,'2026-10-26 19:01:01'),(4,'fracciones-sin-miedo','Fracciones sin miedo','Matemáticas','Leer, comparar, sumar y calcular fracciones con ejemplos de todos los días.',NULL,NULL,NULL,NULL,'publicado',1,'2026-10-26 19:01:01'),(5,'clase-61ec21b05d','El ciclo del agua en el Chocó','Clase propia','Creado a partir del texto del docente.',1,'AGUA26','secundaria','El ciclo del agua en el Chocó\n\nEl Chocó es uno de los lugares más lluviosos del planeta. En municipios como Lloró y Tutunendo llueve casi todos los días del año. La evaporación es el paso del agua líquida a vapor gracias al calor del Sol. El vapor sube a la atmósfera, se enfría y forma nubes. La condensación es el cambio del vapor de agua a pequeñas gotas líquidas. Cuando las gotas se unen y pesan demasiado, caen como lluvia. La precipitación es el agua que cae de las nubes en forma de lluvia, granizo o nieve.\n\nEn la selva del Pacífico, los árboles devuelven agua al aire por sus hojas. La transpiración es la salida de vapor de agua a través de las hojas de las plantas. Parte de la lluvia corre por la superficie y llega a quebradas y ríos. La infiltración es el paso del agua de lluvia hacia el interior del suelo.\n\nEl río Atrato recoge el agua de muchas quebradas y la lleva hasta el golfo de Urabá. El río San Juan lleva sus aguas hasta el océano Pacífico. Los bosques protegen los suelos y ayudan a que los ríos tengan agua todo el año. Cuando se talan los bosques, la lluvia arrastra la tierra y los ríos se llenan de sedimentos. Cuidar el bosque del Chocó también es cuidar el ciclo del agua.','publicado',0,'2026-10-26 19:01:01');
