INSERT INTO `ejercicios` VALUES (1,1,1,'test','¿Cómo se dice «buenos días» en inglés?','{\"opciones\":[\"Good morning\",\"Good night\",\"Good afternoon\"]}','{\"indice\":0}','«Good night» es para despedirse en la noche y «Good afternoon» es «buenas tardes».',NULL),(2,1,2,'si_no','«Goodbye» significa «adiós».','[]','{\"valor\":\"si\"}','Goodbye = adiós. También se usa «Bye».',NULL),(3,1,3,'completar','___ are you? — I’m fine, thank you.','{\"banco\":[\"How\",\"What\",\"Who\",\"Where\"]}','{\"respuestas\":[\"How\"]}','«How are you?» significa «¿Cómo estás?».',NULL),(4,1,4,'ordenar_palabras','Ordena la frase en inglés: «Mucho gusto».','[]','{\"frase\":\"Nice to meet you\"}','«Nice to meet you».',NULL),(5,1,5,'ordenar_letras','Ordena las letras para formar la palabra.','{\"pista\":\"Saludo que sirve a cualquier hora: «hola».\"}','{\"palabra\":\"Hello\"}','La palabra es «Hello».',NULL),(6,1,6,'test','Son las 9 de la noche y te despides de tu familia. ¿Qué dices?','{\"opciones\":[\"Good night\",\"Good morning\",\"Hello\"]}','{\"indice\":0}','«Good night» se usa para despedirse en la noche o antes de dormir.',NULL),(7,1,7,'si_no','«See you later» significa «hasta luego».','[]','{\"valor\":\"si\"}','Literalmente: «te veo después».',NULL),(8,1,8,'relacionar','Une cada saludo con su significado.','[]','{\"pares\":[[\"Good morning\",\"Buenos días\"],[\"Good afternoon\",\"Buenas tardes\"],[\"Good evening\",\"Buenas noches (al llegar)\"],[\"Goodbye\",\"Adiós\"]]}',NULL,NULL),(9,1,9,'completar','Good ___, teacher! (Son las 3 de la tarde)','{\"banco\":[\"afternoon\",\"morning\",\"night\",\"evening\"]}','{\"respuestas\":[\"afternoon\"]}','Por la tarde se saluda con «Good afternoon».',NULL),(10,1,10,'si_no','«Hello» solo se puede usar por la mañana.','[]','{\"valor\":\"no\"}','«Hello» sirve a cualquier hora del día.',NULL),(11,2,1,'test','¿Qué pregunta significa «¿Cómo te llamas?»?','{\"opciones\":[\"What is your name?\",\"How old are you?\",\"Where are you from?\"]}','{\"indice\":0}','«What is your name?» pregunta por el nombre.',NULL),(12,2,2,'completar','My ___ is Ana.','{\"banco\":[\"name\",\"age\",\"from\",\"are\"]}','{\"respuestas\":[\"name\"]}','«My name is…» = «Mi nombre es…».',NULL),(13,2,3,'ordenar_palabras','Ordena la frase en inglés: «Soy de Colombia».','[]','{\"frase\":\"I am from Colombia\"}','«I am from Colombia».',NULL),(14,2,4,'si_no','«How old are you?» pregunta por la edad.','[]','{\"valor\":\"si\"}','Old = viejo; la pregunta significa «¿Cuántos años tienes?».',NULL),(15,2,5,'ordenar_letras','Ordena las letras para formar la palabra.','{\"pista\":\"En «My ___ is Carlos», la palabra que significa «nombre».\"}','{\"palabra\":\"Name\"}','La palabra es «Name».',NULL),(16,2,6,'test','Te preguntan «Where are you from?». ¿Qué respondes?','{\"opciones\":[\"I’m from Quibdó\",\"I’m twelve\",\"I’m fine\"]}','{\"indice\":0}','«Where are you from?» pregunta de dónde eres.',NULL),(17,2,7,'completar','I ___ fourteen years old.','{\"banco\":[\"am\",\"is\",\"are\",\"have\"]}','{\"respuestas\":[\"am\",\"’m\",\"\'m\"]}','En inglés la edad se dice con el verbo «to be»: I am fourteen.',NULL),(18,2,8,'relacionar','Une cada pregunta con su respuesta.','[]','{\"pares\":[[\"What is your name?\",\"My name is Luis\"],[\"How old are you?\",\"I am fifteen\"],[\"Where are you from?\",\"I am from Cali\"],[\"How are you?\",\"I am fine\"]]}',NULL,NULL),(19,2,9,'si_no','«I have 15 years» es la forma correcta de decir tu edad.','[]','{\"valor\":\"no\"}','Se dice «I am 15» o «I am 15 years old».',NULL),(20,2,10,'ordenar_palabras','Ordena la pregunta en inglés: «¿Cuál es tu nombre?».','[]','{\"frase\":\"What is your name\"}','«What is your name».',NULL),(21,3,1,'test','¿Qué es «a pencil»?','{\"opciones\":[\"Un lápiz\",\"Un borrador\",\"Un cuaderno\"]}','{\"indice\":0}','Pencil = lápiz; pen = bolígrafo.',NULL),(22,3,2,'ordenar_letras','Ordena las letras para formar la palabra.','{\"pista\":\"Lo lees en clase: «libro».\"}','{\"palabra\":\"Book\"}','La palabra es «Book».',NULL),(23,3,3,'si_no','«Notebook» significa «cuaderno».','[]','{\"valor\":\"si\"}','También se usa para un computador portátil, pero en el salón es el cuaderno.',NULL),(24,3,4,'completar','Can I borrow your ___? I need to erase this.','{\"banco\":[\"eraser\",\"ruler\",\"pen\",\"chair\"]}','{\"respuestas\":[\"eraser\"]}','Eraser = borrador.',NULL),(25,3,5,'relacionar','Une cada objeto con su nombre en español.','[]','{\"pares\":[[\"Ruler\",\"Regla\"],[\"Chair\",\"Silla\"],[\"Board\",\"Tablero\"],[\"Backpack\",\"Morral\"]]}',NULL,NULL),(26,3,6,'test','El profesor dice «Open your books, please». ¿Qué pide?','{\"opciones\":[\"Abrir los libros\",\"Cerrar los libros\",\"Leer en voz alta\"]}','{\"indice\":0}','Open = abrir; close = cerrar.',NULL),(27,3,7,'ordenar_palabras','Ordena la frase en inglés: «Este es mi morral».','[]','{\"frase\":\"This is my backpack\"}','«This is my backpack».',NULL),(28,3,8,'si_no','«Desk» significa «pupitre» o «escritorio».','[]','{\"valor\":\"si\"}','Desk es la mesa donde trabajas.',NULL),(29,3,9,'completar','There are thirty ___ in my classroom. (sillas)','{\"banco\":[\"chairs\",\"chair\",\"tables\",\"desk\"]}','{\"respuestas\":[\"chairs\"]}','Plural regular: chair → chairs.',NULL),(30,3,10,'ordenar_letras','Ordena las letras para formar la palabra.','{\"pista\":\"Escribes y borras con él: «lápiz».\"}','{\"palabra\":\"Pencil\"}','La palabra es «Pencil».',NULL),(31,4,1,'test','¿Qué significa «Sit down, please»?','{\"opciones\":[\"Siéntate, por favor\",\"Ponte de pie, por favor\",\"Sal, por favor\"]}','{\"indice\":0}','Sit down = sentarse; stand up = ponerse de pie.',NULL),(32,4,2,'completar','I ___ to school every day.','{\"banco\":[\"go\",\"goes\",\"going\",\"gone\"]}','{\"respuestas\":[\"go\"]}','Con «I» el verbo va sin -s: I go.',NULL),(33,4,3,'si_no','«She go to school» está bien escrito.','[]','{\"valor\":\"no\"}','Con she, he o it se agrega -s o -es: she goes.',NULL),(34,4,4,'ordenar_palabras','Ordena la frase en inglés: «Tenemos inglés el lunes».','[]','{\"frase\":\"We have English on Monday\"}','«We have English on Monday».',NULL),(35,4,5,'relacionar','Une cada día con su nombre en inglés.','[]','{\"pares\":[[\"Lunes\",\"Monday\"],[\"Miércoles\",\"Wednesday\"],[\"Viernes\",\"Friday\"],[\"Domingo\",\"Sunday\"]]}',NULL,NULL),(36,4,6,'test','¿Cuál es la forma correcta?','{\"opciones\":[\"He studies math\",\"He study math\",\"He studys math\"]}','{\"indice\":0}','Study termina en consonante + y: con he cambia a studies.',NULL),(37,4,7,'ordenar_letras','Ordena las letras para formar la palabra.','{\"pista\":\"El primer día de la semana escolar, en inglés.\"}','{\"palabra\":\"Monday\"}','La palabra es «Monday».',NULL),(38,4,8,'si_no','«Homework» significa «tarea».','[]','{\"valor\":\"si\"}','Homework = trabajo para hacer en casa.',NULL),(39,4,9,'completar','Can you repeat that, ___? (por favor)','{\"banco\":[\"please\",\"thanks\",\"sorry\",\"hello\"]}','{\"respuestas\":[\"please\"]}','Please = por favor.',NULL),(40,4,10,'ordenar_palabras','Ordena la frase en inglés: «Hago mi tarea en la noche».','[]','{\"frase\":\"I do my homework at night\"}','«I do my homework at night».',NULL),(41,5,1,'test','¿En qué estado está el agua del hielo?','{\"opciones\":[\"Sólido\",\"Líquido\",\"Gaseoso\"]}','{\"indice\":0}','El hielo es agua en estado sólido.',NULL),(42,5,2,'si_no','A nivel del mar, el agua pura hierve a 100 °C.','[]','{\"valor\":\"si\"}','A mayor altura hierve a menos temperatura; en Bogotá, cerca de 92 °C.',NULL),(43,5,3,'completar','Cuando el agua pasa de líquido a gas ocurre la ___.','{\"banco\":[\"evaporación\",\"condensación\",\"fusión\",\"solidificación\"]}','{\"respuestas\":[\"evaporación\"]}','Evaporación: de líquido a gas.',NULL),(44,5,4,'relacionar','Une cada cambio con su nombre.','[]','{\"pares\":[[\"Líquido a gas\",\"Evaporación\"],[\"Gas a líquido\",\"Condensación\"],[\"Sólido a líquido\",\"Fusión\"],[\"Líquido a sólido\",\"Solidificación\"]]}',NULL,NULL),(45,5,5,'ordenar_letras','Ordena las letras para formar la palabra.','{\"pista\":\"El agua en estado gaseoso se llama ___ de agua.\"}','{\"palabra\":\"Vapor\"}','La palabra es «Vapor».',NULL),(46,5,6,'si_no','El agua pura se congela a 10 °C.','[]','{\"valor\":\"no\"}','A presión normal se congela a 0 °C.',NULL),(47,5,7,'test','¿Qué necesita el hielo para derretirse?','{\"opciones\":[\"Recibir calor\",\"Perder calor\",\"Estar a oscuras\"]}','{\"indice\":0}','Al recibir calor pasa de sólido a líquido (fusión).',NULL),(48,5,8,'ordenar_palabras','Ordena las palabras para formar la frase.','[]','{\"frase\":\"El hielo se derrite con el calor\"}','«El hielo se derrite con el calor».',NULL),(49,5,9,'completar','Las nubes están formadas por gotas de agua y cristales de ___.','{\"banco\":[\"hielo\",\"sal\",\"arena\",\"humo\"]}','{\"respuestas\":[\"hielo\"]}','En lo alto hace frío y parte del agua se congela.',NULL),(50,5,10,'si_no','El agua es la misma sustancia en sus tres estados.','[]','{\"valor\":\"si\"}','Cambia la forma y la energía de sus partículas, no la sustancia.',NULL),(51,6,1,'test','¿Qué fuente de energía mueve el ciclo del agua?','{\"opciones\":[\"El Sol\",\"La Luna\",\"Los volcanes\"]}','{\"indice\":0}','El calor del Sol evapora el agua; la gravedad la hace caer.',NULL),(52,6,2,'completar','El vapor sube, se enfría y forma nubes por ___.','{\"banco\":[\"condensación\",\"evaporación\",\"infiltración\",\"fusión\"]}','{\"respuestas\":[\"condensación\"]}','Condensación: de gas a líquido.',NULL),(53,6,3,'si_no','La precipitación puede ser lluvia, granizo o nieve.','[]','{\"valor\":\"si\"}','Es toda el agua que cae de las nubes.',NULL),(54,6,4,'ordenar_palabras','Ordena las palabras para formar la frase.','[]','{\"frase\":\"El agua cae de las nubes como lluvia\"}','«El agua cae de las nubes como lluvia».',NULL),(55,6,5,'relacionar','Une cada etapa con lo que pasa.','[]','{\"pares\":[[\"Evaporación\",\"El agua sube como vapor\"],[\"Condensación\",\"Se forman las nubes\"],[\"Precipitación\",\"El agua cae\"],[\"Infiltración\",\"El agua entra al suelo\"]]}',NULL,NULL),(56,6,6,'test','¿Cómo se llama el vapor de agua que liberan las plantas por sus hojas?','{\"opciones\":[\"Transpiración\",\"Fotosíntesis\",\"Erosión\"]}','{\"indice\":0}','Las plantas devuelven agua al aire por transpiración.',NULL),(57,6,7,'ordenar_letras','Ordena las letras para formar la palabra.','{\"pista\":\"Precipitación en forma de gotas de agua.\"}','{\"palabra\":\"Lluvia\"}','La palabra es «Lluvia».',NULL),(58,6,8,'si_no','El agua que se infiltra en el suelo puede formar aguas subterráneas.','[]','{\"valor\":\"si\"}','Se acumula en acuíferos que alimentan pozos y manantiales.',NULL),(59,6,9,'completar','El Chocó es una de las regiones más ___ del planeta.','{\"banco\":[\"lluviosas\",\"secas\",\"frías\",\"desérticas\"]}','{\"respuestas\":[\"lluviosas\"]}','En municipios como Lloró llueve casi todo el año.',NULL),(60,6,10,'test','¿Qué pasa con el agua después de llover?','{\"opciones\":[\"Corre o se infiltra y vuelve a evaporarse\",\"Desaparece para siempre\",\"Se convierte en sal\"]}','{\"indice\":0}','Por eso se llama ciclo: el agua se recicla.',NULL),(61,7,1,'test','¿Cuál es el río más importante de Colombia por su longitud y su cuenca?','{\"opciones\":[\"Magdalena\",\"Atrato\",\"Bogotá\"]}','{\"indice\":0}','El Magdalena recorre el país de sur a norte.',NULL),(62,7,2,'si_no','El río Atrato atraviesa el Chocó y desemboca en el golfo de Urabá.','[]','{\"valor\":\"si\"}','Pasa por Quibdó y llega al mar Caribe por el golfo de Urabá.',NULL),(63,7,3,'completar','El río Magdalena desemboca en el mar ___.','{\"banco\":[\"Caribe\",\"Pacífico\",\"Muerto\",\"Mediterráneo\"]}','{\"respuestas\":[\"Caribe\"]}','Llega al mar Caribe en Bocas de Ceniza, junto a Barranquilla.',NULL),(64,7,4,'relacionar','Une cada río con el lugar al que llega.','[]','{\"pares\":[[\"Magdalena\",\"Mar Caribe, en Bocas de Ceniza\"],[\"Atrato\",\"Golfo de Urabá\"],[\"San Juan\",\"Océano Pacífico\"],[\"Amazonas\",\"Océano Atlántico, en Brasil\"]]}',NULL,NULL),(65,7,5,'ordenar_letras','Ordena las letras para formar la palabra.','{\"pista\":\"Río del Chocó que pasa por Quibdó.\"}','{\"palabra\":\"Atrato\"}','La palabra es «Atrato».',NULL),(66,7,6,'si_no','El río San Juan desemboca en el mar Caribe.','[]','{\"valor\":\"no\"}','El San Juan desemboca en el océano Pacífico.',NULL),(67,7,7,'test','¿Qué es una cuenca hidrográfica?','{\"opciones\":[\"El territorio cuyas aguas van a un mismo río\",\"Un tipo de nube\",\"Un lago artificial\"]}','{\"indice\":0}','Toda la lluvia de una cuenca termina en el mismo río.',NULL),(68,7,8,'ordenar_palabras','Ordena las palabras para formar la frase.','[]','{\"frase\":\"Quibdó está a orillas del río Atrato\"}','«Quibdó está a orillas del río Atrato».',NULL),(69,7,9,'completar','El río Cauca es el principal ___ del Magdalena.','{\"banco\":[\"afluente\",\"delta\",\"océano\",\"glaciar\"]}','{\"respuestas\":[\"afluente\"]}','Un afluente es un río que desemboca en otro.',NULL),(70,7,10,'si_no','Un afluente es un río que lleva sus aguas a otro río.','[]','{\"valor\":\"si\"}','Por ejemplo, el Cauca es afluente del Magdalena.',NULL),(71,8,1,'test','¿Cuál de estas acciones ahorra agua en casa?','{\"opciones\":[\"Cerrar la llave mientras te cepillas\",\"Lavar el patio con manguera\",\"Dejar el grifo goteando\"]}','{\"indice\":0}','Una llave abierta gasta varios litros por minuto.',NULL),(72,8,2,'si_no','El mercurio usado en la minería ilegal contamina los ríos.','[]','{\"valor\":\"si\"}','El mercurio es tóxico y se acumula en los peces y en las personas.',NULL),(73,8,3,'completar','Casi toda el agua de la Tierra es ___; solo una pequeña parte es dulce.','{\"banco\":[\"salada\",\"dulce\",\"potable\",\"helada\"]}','{\"respuestas\":[\"salada\"]}','Cerca del 97 % del agua del planeta está en los océanos.',NULL),(74,8,4,'ordenar_palabras','Ordena las palabras para formar la frase.','[]','{\"frase\":\"Cuidar los ríos es cuidar la vida\"}','«Cuidar los ríos es cuidar 