/*!40000 ALTER TABLE `perfiles` DISABLE KEYS */;
INSERT INTO `perfiles` VALUES (1,'docente','entre_clases',NULL,NULL,'secundaria',10,'test,si_no,completar,ordenar_palabras,ordenar_letras,relacionar',NULL,'El ciclo del agua en el Chocó\n\nEl Chocó es uno de los lugares más lluviosos del planeta. En municipios como Lloró y Tutunendo llueve casi todos los días del año. La evaporación es el paso del agua líquida a vapor gracias al calor del Sol. El vapor sube a la atmósfera, se enfría y forma nubes. La condensación es el cambio del vapor de agua a pequeñas gotas líquidas. Cuando las gotas se unen y pesan demasiado, caen como lluvia. La precipitación es el agua que cae de las nubes en forma de lluvia, granizo o nieve.\n\nEn la selva del Pacífico, los árboles devuelven agua al aire por sus hojas. La transpiración es la salida de vapor de agua a través de las hojas de las plantas. Parte de la lluvia corre por la superficie y llega a quebradas y ríos. La infiltración es el paso del agua de lluvia hacia el interior del suelo.\n\nEl río Atrato recoge el agua de muchas quebradas y la lleva hasta el golfo de Urabá. El río San Juan lleva sus aguas hasta el océano Pacífico. Los bosques protegen los suelos y ayudan a que los ríos tengan agua todo el año. Cuando se talan los bosques, la lluvia arrastra la tierra y los ríos se llenan de sedimentos. Cuidar el bosque del Chocó también es cuidar el ciclo del agua.',1,'2026-10-26 19:01:01'),(2,'estudiante','reforzar',2,'cero',NULL,10,'test,si_no,completar,ordenar_palabras,ordenar_letras,relacionar',NULL,NULL,1,'2026-10-26 19:01:01');
/*!40000 ALTER TABLE `perfiles` ENABLE KEYS */;
